// SessionCoreServer is the server API for SessionCore service.
// All implementations must embed UnimplementedSessionCoreServer
// for forward compatibility.
//
// SessionCore — authoritative state for thread timeline, run metadata,
// checkpoints, instruction loading, compaction summaries, and auto-memory index.
// Single writer for threads, messages, runs, and checkpoints.
type SessionCoreServer interface {
	// Create a new conversation thread within a session.
	CreateThread(context.Context, *CreateThreadRequest) (*CreateThreadResponse, error)
	// Append a message (user, assistant, or system) to a thread.
	AppendMessage(context.Context, *AppendMessageRequest) (*AppendMessageResponse, error)
	// Start a new run within a thread.
	StartRun(context.Context, *StartRunRequest) (*StartRunResponse, error)
	// Start one prepared, deterministic service-owned scheduled run. This is
	// intentionally distinct from StartRun: only orchestrator-core may use a
	// thread that Capability Core prepared for a freshly authorized cron fire.
	StartScheduledRun(context.Context, *StartScheduledRunRequest) (*StartRunResponse, error)
	// Prepare the deterministic service-owned thread for one freshly
	// Control-authorized schedule fire. The decision bearer is consumed only by
	// this RPC and is never persisted or forwarded to Temporal.
	PrepareScheduledRunThread(context.Context, *PrepareScheduledRunThreadRequest) (*PrepareScheduledRunThreadResponse, error)
	// Create-or-reuse a durable thread owned by a REAL user (never a service
	// principal), with a caller-named origin, keyed by session_key for
	// idempotency (chat-wave2 "schedule"/"mail-task" specs, 2026-09-28 —
	// the reusable "service creates or reuses a thread owned by user U,
	// readable by U, with a named origin" seam). Unlike
	// PrepareScheduledRunThread, which always mints a service-owned,
	// Space-authority-bound thread, this RPC's thread IS owned by the given
	// user_id, so it is trivially readable through the existing owner-bound
	// path (ListThreads' default user_id filter) -- no Control decision, no
	// Space authority, is required to read it back. Restricted to an allow-
	// listed set of trusted service callers; never reachable by a live user's
	// own bearer.
	PrepareUserOwnedThread(context.Context, *PrepareUserOwnedThreadRequest) (*PrepareUserOwnedThreadResponse, error)
	// Record completion of a single step within a run.
	CompleteStep(context.Context, *CompleteStepRequest) (*CompleteStepResponse, error)
	// Durably reserve an inline tool-action audit intent before the tool runs.
	// This does not advance or terminate the run/plan.
	ReserveToolAction(context.Context, *ReserveToolActionRequest) (*ReserveToolActionResponse, error)
	// Finalize a previously reserved inline tool action after execution.
	// This persists the final audit event without changing run/plan lifecycle.
	FinalizeToolAction(context.Context, *FinalizeToolActionRequest) (*FinalizeToolActionResponse, error)
	// Persist a checkpoint snapshot for a run.
	SaveCheckpoint(context.Context, *SaveCheckpointRequest) (*SaveCheckpointResponse, error)
	// Save the durable loop's fold for a run (build plan WS03 S4). Latest wins,
	// compare-and-set on expected_seq. Refused for a zero-retention or waived run.
	SaveLoopCheckpoint(context.Context, *SaveLoopCheckpointRequest) (*SaveLoopCheckpointResponse, error)
	// Claim a paused or parked run's fold for one continuation. Exactly one claim wins.
	ClaimLoopCheckpoint(context.Context, *ClaimLoopCheckpointRequest) (*ClaimLoopCheckpointResponse, error)
	// Close a run's fold once its loop has finished. Idempotent for a closed row.
	CloseLoopCheckpoint(context.Context, *CloseLoopCheckpointRequest) (*CloseLoopCheckpointResponse, error)
	// Read the effect ledger's rows for named tool calls of one run (build plan WS03
	// S7a). Digest-only: the status, class and argument digest of each action, never
	// its arguments or output. The loop that resumes a run reads it to close a call
	// honestly instead of running it again.
	//
	// Answers only while the loop checkpoint store is switched on (otherwise the same
	// closed "loop_checkpoint_disabled" refusal the checkpoint RPCs give), and only for a
	// run that persists: a zero-retention or waived run never keeps a fold, so it gets the
	// durable-mutation refusal. The caller must be allowed to read the run under the same
	// rule as GetRun, which includes refusing a run whose owner was removed from its
	// Space. Rows written under zero retention are never returned.
	//
	// ABSENCE IS NOT PROOF. An action id missing from the answer is UNKNOWN. It may never
	// have been reserved, may be reserved by a concurrent writer that has not committed
	// yet, or may be a row this read hides. Never read absence as "the call did not run".
	// For an effectful call, only a row with status "not_run" (or a "completed" row with
	// its output) licenses a re-dispatch decision.
	ListToolActions(context.Context, *ListToolActionsRequest) (*ListToolActionsResponse, error)
	// Replay the thread event log as a stream of Events.
	// Ordering: (ts, event_id) with event_id as deterministic tiebreaker.
	ReplayThread(*ReplayThreadRequest, grpc.ServerStreamingServer[Event]) error
	// Assemble the full context window for a model call.
	// Order: policy -> workspace -> agent -> user -> thread recent -> episodic
	//        -> skill index -> skill expansion -> retrieval snippets -> current prompt/tool output.
	GetContextAssembly(context.Context, *GetContextAssemblyRequest) (*GetContextAssemblyResponse, error)
	// Trigger on-demand checkpoint compaction for all runs with pending events.
	CompactNow(context.Context, *CompactNowRequest) (*CompactNowResponse, error)
	// Upsert a learned/edited agent skill body (closed learning loop, G7).
	// session-core owns the `agent_skills` table (skill bodies); capability-core's
	// registry is the catalog over these rows. Provenance-protected: a
	// `background_review` upsert never overwrites a `user`-authored skill.
	UpsertAgentSkill(context.Context, *UpsertAgentSkillRequest) (*UpsertAgentSkillResponse, error)
	// List an org's agent skills (the read path for the gateway's MatchSkills
	// cache, G7's "last mile"): learned skills persisted via UpsertAgentSkill are
	// read back here so they become usable in inference, not just stored.
	// Org-scoped — only the caller's org's skills are returned.
	ListAgentSkills(context.Context, *ListAgentSkillsRequest) (*ListAgentSkillsResponse, error)
	// SetAgentSkillEnabled — flip one skill's injection switch by id.
	//
	// UpsertAgentSkill cannot do this: it is keyed by (org_id, name) and upserts
	// the WHOLE skill, so calling it with only `enabled` would blank the content,
	// triggers and restrictions of the skill it was meant to pause. The quality
	// policy needs to stop injecting a skill without destroying it, which is
	// precisely what that would do.
	SetAgentSkillEnabled(context.Context, *SetAgentSkillEnabledRequest) (*SetAgentSkillEnabledResponse, error)
	// List a thread's conversation messages in order (the durable transcript
	// source for the G7 learning review). Distinct from the gateway's in-memory
	// ListThreadMessages cache — this reads the session-core system-of-record.
	// Org-scoped via the owning thread, so a caller reads only its own org's
	// conversation.
	ListConversation(context.Context, *ListConversationRequest) (*ListConversationResponse, error)
	// List an authenticated user's durable conversation threads for cross-device
	// chat history. Timestamps are based on creation/message writes, never reads.
	ListThreads(context.Context, *ListThreadsRequest) (*ListThreadsResponse, error)
	// Set user-facing presentation attributes for a thread. Session Core remains
	// the single writer; edge gateways may normalize the request but must not
	// keep a competing history index or presentation cache.
	UpdateThreadPresentation(context.Context, *UpdateThreadPresentationRequest) (*UpdateThreadPresentationResponse, error)
	// Hide one thread from the user's ordinary history without erasing its
	// append-only model/audit evidence. Data-subject erasure is a separate,
	// explicitly authorized Control-Plane workflow.
	ArchiveThread(context.Context, *ArchiveThreadRequest) (*ArchiveThreadResponse, error)
	// Archive every currently visible thread for one authenticated user. This is
	// the durable equivalent of "clear chat history" in a client sidebar.
	ArchiveThreads(context.Context, *ArchiveThreadsRequest) (*ArchiveThreadsResponse, error)
	// Permanently erase one thread and its thread-owned durable evidence. This is
	// owner-bound: Session Core checks the verified caller against the thread's
	// user (or exact system owner) before deleting any row.
	DeleteThread(context.Context, *DeleteThreadRequest) (*DeleteThreadResponse, error)
	// Permanently erase every thread owned by one authenticated user. This is
	// the durable equivalent of a destructive "clear chat history" action.
	DeleteThreads(context.Context, *DeleteThreadsRequest) (*DeleteThreadsResponse, error)
	// Permanently erase the threads explicitly bound to a Space for its owner.
	// This is a Control-authorized data-subject deletion operation, available
	// only to the exact deletion coordinator service; it is not a general
	// service-user impersonation API.
	DeleteSpaceThreads(context.Context, *DeleteSpaceThreadsRequest) (*DeleteSpaceThreadsResponse, error)
	// Set a run's mode (execute | plan | reactive | research) durably on the
	// run record (ROADMAP P3). The gateway's in-memory plan-mode cache
	// write-throughs here so plan mode survives restart — auditability/resume
	// (GOAL.md §7). The in-memory cache stays authoritative for the request.
	SetRunMode(context.Context, *SetRunModeRequest) (*SetRunModeResponse, error)
	// Claim one service-owned scheduled step before Execution Core dispatches
	// it. The request is content-free and must match the deterministic run
	// bindings persisted by StartScheduledRun. A duplicate claim returns the
	// original receipt and never opens a second effect attempt.
	ClaimScheduledStep(context.Context, *ClaimScheduledStepRequest) (*ClaimScheduledStepResponse, error)
	// Record the metadata-only outcome for a previously claimed scheduled step.
	// `unknown_outcome` is explicit: a lost transport response is not converted
	// into success or an immediate blind retry.
	RecordScheduledStepReceipt(context.Context, *RecordScheduledStepReceiptRequest) (*RecordScheduledStepReceiptResponse, error)
	// Stamp how a run's context was assembled onto the run record
	// (`runs.metadata.run_context`). Counts and closed tokens only; refused for
	// zero-retention and waived credentials like every durable run mutation.
	RecordRunContext(context.Context, *RecordRunContextRequest) (*RecordRunContextResponse, error)
	// Persist the answer of a claimed scheduled step into the scheduled thread
	// and complete its receipt in one transaction. Idempotent on (run_id,
	// step_id). Refused for zero-retention and waived runs. Off unless
	// SESSION_CORE_SCHEDULED_RESULT_PERSIST is `true`; off keeps the receipt-only
	// path. `output` is content and is accepted only on this direct hop.
	RecordScheduledRunResult(context.Context, *RecordScheduledRunResultRequest) (*RecordScheduledRunResultResponse, error)
	mustEmbedUnimplementedSessionCoreServer()
}

